CREATE TYPE "SupplierBankingProfileStatus" AS ENUM ('DRAFT','SUBMITTED','CHANGE_PENDING','SUSPENDED');
CREATE TYPE "SupplierBankingVerificationStatus" AS ENUM ('PENDING','VERIFIED','REJECTED','REVOKED');
CREATE TABLE "SupplierBankingProfile" ("id" TEXT NOT NULL,"sellerTenantId" TEXT NOT NULL,"status" "SupplierBankingProfileStatus" NOT NULL DEFAULT 'DRAFT',"accountHolderName" TEXT NOT NULL,"bankName" TEXT NOT NULL,"bankCountryCode" TEXT NOT NULL,"currencyCode" TEXT NOT NULL DEFAULT 'USD',"accountType" TEXT,"accountNumberLast4" TEXT NOT NULL,"routingNumberLast4" TEXT,"swiftBic" TEXT,"ibanLast4" TEXT,"encryptedAccountData" TEXT NOT NULL,"submittedByUserId" TEXT,"submittedAt" TIMESTAMP(3),"lastChangedByUserId" TEXT,"lastChangedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SupplierBankingProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupplierBankingVerification" ("id" TEXT NOT NULL,"buyerTenantId" TEXT NOT NULL,"sellerTenantId" TEXT NOT NULL,"buyerSupplierId" TEXT NOT NULL,"bankingProfileId" TEXT NOT NULL,"status" "SupplierBankingVerificationStatus" NOT NULL DEFAULT 'PENDING',"verifiedByUserId" TEXT,"verifiedAt" TIMESTAMP(3),"rejectedByUserId" TEXT,"rejectedAt" TIMESTAMP(3),"rejectionReason" TEXT,"revokedByUserId" TEXT,"revokedAt" TIMESTAMP(3),"revocationReason" TEXT,"profileFingerprint" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SupplierBankingVerification_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupplierBankingProfile_sellerTenantId_key" ON "SupplierBankingProfile"("sellerTenantId");
CREATE INDEX "SupplierBankingProfile_status_updatedAt_idx" ON "SupplierBankingProfile"("status","updatedAt");
CREATE UNIQUE INDEX "SupplierBankingVerification_buyerTenantId_sellerTenantId_key" ON "SupplierBankingVerification"("buyerTenantId","sellerTenantId");
CREATE INDEX "SupplierBankingVerification_buyerTenantId_status_updatedAt_idx" ON "SupplierBankingVerification"("buyerTenantId","status","updatedAt");
CREATE INDEX "SupplierBankingVerification_buyerSupplierId_status_idx" ON "SupplierBankingVerification"("buyerSupplierId","status");
CREATE INDEX "SupplierBankingVerification_sellerTenantId_status_idx" ON "SupplierBankingVerification"("sellerTenantId","status");
